create table refund_policy_intake_snapshots(id uuid not null,tenant_id uuid not null,rules_version text not null check(rules_version='refund-policy-intake.v1'),action_plan_id uuid not null,action_package_id uuid not null,input_sha256 char(64) not null,status text not null check(status='waiting_facts'),fact_level text not null check(fact_level='F4'),source_finding_count integer not null check(source_finding_count=7),field_count integer not null check(field_count=7),fields jsonb not null check(jsonb_typeof(fields)='array'),paths jsonb not null check(jsonb_typeof(paths)='array'),completeness_rules jsonb not null check(jsonb_typeof(completeness_rules)='array'),conflict_rules jsonb not null check(jsonb_typeof(conflict_rules)='array'),missing_inputs jsonb not null check(jsonb_typeof(missing_inputs)='array'),summary_draft_authorized boolean not null check(summary_draft_authorized=false),publication_authorized boolean not null check(publication_authorized=false),created_at timestamptz not null,primary key(tenant_id,id),unique(tenant_id,input_sha256),foreign key(tenant_id,action_plan_id) references optimization_action_plan_snapshots(tenant_id,id));create trigger refund_policy_intake_snapshots_append_only before update or delete on refund_policy_intake_snapshots for each row execute function reject_immutable_mutation();create trigger refund_policy_intake_snapshots_no_truncate before truncate on refund_policy_intake_snapshots for each statement execute function reject_immutable_mutation();alter table refund_policy_intake_snapshots enable row level security;alter table refund_policy_intake_snapshots force row level security;create policy refund_policy_intake_snapshots_tenant_isolation on refund_policy_intake_snapshots using(tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid) with check(tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid);
